import{_ as o,o as t,c as e,a2 as l}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"ZViewer 主题系统 — 新手入门教程","description":"","frontmatter":{},"headers":[],"relativePath":"features/themes.md","filePath":"features/themes.md","lastUpdated":1785772843000}'),a={name:"features/themes.md"};function i(n,r,s,g,h,u){return t(),e("div",null,[...r[0]||(r[0]=[l('<h1 id="zviewer-主题系统-—-新手入门教程" tabindex="-1">ZViewer 主题系统 — 新手入门教程 <a class="header-anchor" href="#zviewer-主题系统-—-新手入门教程" aria-label="Permalink to &quot;ZViewer 主题系统 — 新手入门教程&quot;">​</a></h1><p>ZViewer 的主题系统让界面颜色随你的壁纸自动变化，无需手动配色。下面是完整的新手指南。</p><hr><h2 id="功能概述" tabindex="-1">功能概述 <a class="header-anchor" href="#功能概述" aria-label="Permalink to &quot;功能概述&quot;">​</a></h2><p>ZViewer 集成了 <strong>Material You</strong>（Material Design 3）动态主题引擎。简单说就是：</p><ul><li>你换一张手机壁纸，ZViewer 的界面颜色（标题栏、按钮、菜单、选中状态）会自动跟着改变。</li><li>颜色从壁纸中提取的主色、辅助色、强调色智能生成，整体协调统一。</li><li>即使不换壁纸，你也可以手动微调明暗、背景、玻璃效果，打造自己的专属风格。</li></ul><blockquote><p><strong>小技巧：</strong> 如果刚安装 ZViewer，建议先换一张喜欢的壁纸，再打开主题设置——你会看到颜色瞬间变化。</p></blockquote><hr><h2 id="如何进入主题设置" tabindex="-1">如何进入主题设置 <a class="header-anchor" href="#如何进入主题设置" aria-label="Permalink to &quot;如何进入主题设置&quot;">​</a></h2><p>打开 ZViewer，<strong>右上角</strong>有一个调色板图标按钮（🎨 或方形色块图标）。</p><ul><li>点击该按钮，弹出 <strong>主题设置面板</strong>。</li><li>面板分为几个区域：<strong>模式切换</strong>、<strong>壁纸取色</strong>、<strong>背景图片</strong>、<strong>玻璃效果</strong>、<strong>动画设置</strong>。</li></ul><blockquote><p><strong>小技巧：</strong> 如果找不到按钮，检查当前是否在全屏模式下——全屏模式会隐藏顶部栏，需要先退出全屏。</p></blockquote><hr><h2 id="深色-浅色模式切换" tabindex="-1">深色 / 浅色模式切换 <a class="header-anchor" href="#深色-浅色模式切换" aria-label="Permalink to &quot;深色 / 浅色模式切换&quot;">​</a></h2><p>在主题设置面板顶部，有一个 <strong>「深色模式」</strong> 开关（或亮/暗切换按钮）。</p><ul><li><strong>关闭</strong>（浅色模式）：白底深字，适合白天、光线充足的环境。</li><li><strong>开启</strong>（深色模式）：黑底浅字，适合夜间、暗光环境，减少眼睛疲劳。</li></ul><p>切换后，所有界面元素（包括工具栏、状态栏、菜单）都会立即适配。</p><blockquote><p><strong>小技巧：</strong> 深色模式下，壁纸提取的颜色会自动降低饱和度，避免亮色刺眼。</p></blockquote><hr><h2 id="壁纸色彩提取" tabindex="-1">壁纸色彩提取 <a class="header-anchor" href="#壁纸色彩提取" aria-label="Permalink to &quot;壁纸色彩提取&quot;">​</a></h2><p>这是 ZViewer 主题最核心的功能——让界面颜色从壁纸中自动生成。</p><h3 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li>在主题设置面板中找到 <strong>「壁纸」</strong> 或 <strong>「取色来源」</strong> 区域。</li><li>点击 <strong>「选择图片」</strong> 按钮（或相册图标）。</li><li>从系统相册中选取一张图片（壁纸、风景照、插画均可）。</li><li>ZViewer 会自动分析图片，提取出 <strong>主色</strong>、<strong>辅助色</strong>、<strong>强调色</strong>。</li><li>生成的色板会实时预览在界面下方（几个色块排列展示）。</li></ol><h3 id="切换预设色板" tabindex="-1">切换预设色板 <a class="header-anchor" href="#切换预设色板" aria-label="Permalink to &quot;切换预设色板&quot;">​</a></h3><p>如果自动提取的颜色不满意，可以在生成的色板中左右滑动，选择其他备选方案。ZViewer 会提供 4~6 组不同的配色方案供你挑选。</p><blockquote><p><strong>小技巧：</strong> 选择颜色丰富、对比明显的图片，提取效果最好。纯黑/纯白图片提取的颜色会偏少。</p></blockquote><hr><h2 id="自定义背景图片" tabindex="-1">自定义背景图片 <a class="header-anchor" href="#自定义背景图片" aria-label="Permalink to &quot;自定义背景图片&quot;">​</a></h2><p>除了壁纸取色，你还可以给界面设置一张独立的背景图片（不改变配色，仅作为背景装饰）。</p><ol><li>在主题设置面板中找到 <strong>「背景图片」</strong> 区域。</li><li>点击 <strong>「选择图片」</strong>，从相册中选取。</li><li>调整 <strong>「模糊度」</strong> 滑块（0~100），数值越高背景越模糊，文字更清晰。</li><li>开启/关闭 <strong>「暗色遮罩」</strong>——开启后在背景图上覆盖一层半透明黑色，让文字更容易阅读。</li></ol><blockquote><p><strong>小技巧：</strong> 背景图片建议选择纹理简单、亮度均匀的图片，搭配 30~50 的模糊度效果最佳。</p></blockquote><hr><h2 id="玻璃拟态效果" tabindex="-1">玻璃拟态效果 <a class="header-anchor" href="#玻璃拟态效果" aria-label="Permalink to &quot;玻璃拟态效果&quot;">​</a></h2><p>ZViewer 支持 <strong>玻璃拟态（Glassmorphism）</strong> 风格，让界面元素看起来像半透明玻璃。</p><p>在主题设置面板的 <strong>「玻璃效果」</strong> 区域，有两个滑块：</p><ul><li><strong>玻璃强度</strong>（0~100）：控制玻璃效果的可见程度。0 为不透明实心，100 为高度透明。</li><li><strong>模糊度</strong>（0~100）：控制玻璃背后的模糊程度。数值越高，背景透过玻璃越模糊。</li></ul><blockquote><p><strong>小技巧：</strong> 推荐搭配：玻璃强度 40~60 + 模糊度 30~50。太高的强度会让文字看不清，建议同时开启深色模式。</p></blockquote><hr><h2 id="精简动画模式" tabindex="-1">精简动画模式 <a class="header-anchor" href="#精简动画模式" aria-label="Permalink to &quot;精简动画模式&quot;">​</a></h2><p>ZViewer 的界面切换、菜单弹出、页面滚动都带有流畅动画。如果你觉得动画多余或想省电，可以开启 <strong>精简动画模式</strong>。</p><ul><li>在主题设置面板底部找到 <strong>「精简动画」</strong> 开关。</li><li><strong>开启后</strong>：所有动画时长缩短或直接取消，操作响应更干脆。</li><li>适合以下场景： <ul><li>低配置设备</li><li>电量不足时</li><li>追求「即点即开」的快速操作</li></ul></li></ul><blockquote><p><strong>小技巧：</strong> 开启精简动画后，玻璃拟态效果的模糊过渡也会变快，视觉上更利落。</p></blockquote><hr><h2 id="设置自动保存" tabindex="-1">设置自动保存 <a class="header-anchor" href="#设置自动保存" aria-label="Permalink to &quot;设置自动保存&quot;">​</a></h2><p>ZViewer 的主题设置 <strong>全部自动保存</strong>，无需手动点击「保存」按钮。</p><ul><li>每当你调整一个选项（切换模式、选择壁纸、拖动滑块），设置会立即写入本地存储。</li><li>下次打开 ZViewer，所有主题设置自动恢复，与你上次关闭时完全一致。</li></ul><blockquote><p><strong>小技巧：</strong> 如果想恢复默认主题，在主题设置面板底部点击 <strong>「重置为默认」</strong> 即可一键还原。</p></blockquote><hr><h2 id="小技巧汇总" tabindex="-1">小技巧汇总 <a class="header-anchor" href="#小技巧汇总" aria-label="Permalink to &quot;小技巧汇总&quot;">​</a></h2><ul><li><strong>壁纸选择</strong>：色彩丰富、有主次之分的图片提取效果最好。</li><li><strong>深色 + 玻璃</strong>：深色模式下玻璃效果更明显，建议搭配使用。</li><li><strong>背景图片模糊</strong>：背景图片的模糊度建议设置为 30~50，既能看到纹理又不干扰文字。</li><li><strong>精简动画省电</strong>：开启精简动画模式可减少 GPU 渲染，延长续航。</li><li><strong>多试几套色板</strong>：同一张壁纸生成的备选色板中，往往有一款比默认效果更好。</li><li><strong>重置不丢人</strong>：调乱了直接点「重置为默认」，从头再来。</li></ul>',50)])])}const d=o(a,[["render",i]]);export{p as __pageData,d as default};
